local JEUX = {
	ADA = {nom = "Pokemon Platinum (Diamond)", lieux = "sinnoh", global = 0xB70, carte = 0x144C},
	APA = {nom = "Pokemon Platinum (Pearl)", lieux = "sinnoh", global = 0xB70, carte = 0x144C},
	CPU = {nom = "Pokemon Platinum", lieux = "sinnoh", global = 0xBA8, carte = 0x239B0},
	IPK = {nom = "Pokemon HeartGold", lieux = "johto", global = 0xBA8, carte = 0x25FE4, hg = 0xC000},
	IPG = {nom = "Pokemon SoulSilver", lieux = "johto", global = 0xBA8, carte = 0x25FE4, hg = 0xC000},
	IRB = {nom = "Pokemon Black", lieux = "unys", enfant = 0x2592B2, parent = 0x2592B4},
	IRA = {nom = "Pokemon White", lieux = "unys", enfant = 0x2592D2, parent = 0x2592D4},
	IRE = {nom = "Pokemon Black 2", lieux = "unys2", pointeur = 0x24, enfant = 0x41B5C, parent = 0x41B44},
	IRD = {nom = "Pokemon White 2", lieux = "unys2", pointeur = 0x24, enfant = 0x41B5C, parent = 0x41B44},
}

local function u16(a) return memory.read_u16_le(a % 0x1000000, "Main RAM") end
local function u32(a) return memory.read_u32_le(a % 0x1000000, "Main RAM") end

local dossier = (debug.getinfo(1, "S").source:match("^@(.*[\\/])")) or ""
local chemin = dossier .. "carte-ironmon-position.json"

local function json(s)
	return '"' .. tostring(s):gsub('[%c"\\]', function(c) return c == '"' and '\\"' or (c == "\\" and "\\\\" or " ") end) .. '"'
end

local function ecrire(jeu, lieu, carte)
	local f = io.open(chemin, "w")
	if not f then return end
	f:write("{" .. '"jeu":{"nom":' .. json(jeu) .. '},"lieu":' .. json(lieu) .. ',"carte":' .. carte
		.. ',"heure":' .. os.time() .. "}")
	f:close()
end

-- Un numéro de carte qu'on sait nommer (le 0 = « Mystery Zone » veut dire « pas encore en jeu »)
local function valide(table_, n) return n ~= 0 and table_[n] ~= nil end

local decalage = nil -- hg-engine : décidé une fois pour toutes dès qu'une seule des deux lectures est valable
if HG_ENGINE ~= nil then decalage = HG_ENGINE end

local function lireCarte(j, lieux)
	if j.global then
		local version = u32(u32(j.global) + 0x20)
		if version < 0x1000 or version % 0x1000000 >= 0x400000 then return nil end -- partie pas encore chargée
		local base = version % 0x1000000
		local normal = u16(base + j.carte)
		if not j.hg then return normal end
		local decale = u16(base + j.carte + j.hg)
		if decalage == nil then
			local a, b = valide(lieux, normal), valide(lieux, decale)
			if a ~= b then decalage = b end
			return b and decale or normal
		end
		return decalage and decale or normal
	end
	local base = j.pointeur and u32(j.pointeur) % 0x1000000 or 0
	local enfant = u16(base + j.enfant)
	if valide(lieux, enfant) then return enfant end
	return u16(base + j.parent)
end

local code = u32(0x3FFE0C)
local famille = string.char(code % 256, math.floor(code / 0x100) % 256, math.floor(code / 0x10000) % 256)
local j = JEUX[famille]
if not j then
	print("Carte IronMON FR : jeu non reconnu (" .. famille .. "). Jeux pris en charge : DPPt, HGSS, Noire/Blanche 1 et 2.")
	return
end
local lieux = LIEUX[j.lieux]
print("Carte IronMON FR : " .. j.nom .. " reconnu. Fichier à choisir sur la carte :")
print(chemin)

local dernier, image = nil, 0
while true do
	image = image + 1
	if image % 30 == 0 then
		local ok, carte = pcall(lireCarte, j, lieux)
		if ok and carte and valide(lieux, carte) and carte ~= dernier then
			dernier = carte
			ecrire(j.nom, lieux[carte], carte)
		end
	end
	emu.frameadvance()
end
